import { betterAuth, type BetterAuthPlugin } from "better-auth";
import { MongoClient } from "mongodb";
import { mongodbAdapter } from "better-auth/adapters/mongodb";
import { username } from "better-auth/plugins";

const client = new MongoClient(process.env.MONGO_URI!);
const db = client.db();

// Minimal backend setup with username plugin
export const auth = betterAuth({
  database: mongodbAdapter(db, { client }),
  plugins: [
    // Keeping the cast removes type inference, removing it causes TS errors
    username() as BetterAuthPlugin
  ]
});

// Export the inferred session type
export type Session = typeof auth.$Infer.Session;

// Example usage
async function testSessionTypes() {
  const session: Session = {
    session: {
      id: "s1",
      userId: "u1",
      token: "token",
      createdAt: new Date(),
      updatedAt: new Date(),
      expiresAt: new Date()
    },
    user: {
      id: "u1",
      createdAt: new Date(),
      updatedAt: new Date(),
      email: "test@example.com",
      emailVerified: true,
      name: "Test User",
