// auth.ts
import { betterAuth, InferUser } from 'better-auth';
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: 'postgresql://user:password@localhost:5432/mydb',
});

const createAuthInstance = () => {
  return betterAuth({
    baseURL: 'http://localhost:3000',
    secret: 'my-secret',
    database: pool,
    emailAndPassword: {
      enabled: true,
    },
    hooks:  {
      after: createAuthMiddleware(async ({ context: { newSession } }) => {
        if (!newSession) {
          return;
        }

        const { user } = newSession; // ❌ 'user' is typed as 'any'

        console.log(user.email); // No autocomplete, no type checking
      }),
    },
  });
};

export const auth = createAuthInstance();

// Type exports
export type Auth = ReturnType<typeof createAuthInstance>;
export type AuthUser = InferUser<Auth>; // ❌ Resolves to 'any'
```

